/**
 * Self-contained HTML error pages (inline CSS, inline SVG, no scripts, no
 * external requests). One source for:
 *  - public/errors/{404,500,502,503}.html — generated by
 *    `npm run errors:generate`, for the hosting panel / Cloudflare custom error
 *    pages when the Node app itself is unreachable;
 *  - the maintenance-mode 503 served directly by src/proxy.ts.
 * They work without the app, the database or JavaScript.
 */
export type StaticErrorCode = "404" | "500" | "502" | "503";

const ICONS: Record<StaticErrorCode, string> = {
  // lucide: search-x, server-crash, cloud-off, construction (paths inlined)
  "404": '<path d="m13.5 8.5-5 5"/><path d="m8.5 8.5 5 5"/><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>',
  "500": '<path d="M6 10H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v4a2 2 0 0 1-2 2h-2"/><path d="M6 14H4a2 2 0 0 0-2 2v4a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-4a2 2 0 0 0-2-2h-2"/><path d="M6 6h.01"/><path d="M6 18h.01"/><path d="m13 6-4 6h6l-4 6"/>',
  "502": '<path d="m2 2 20 20"/><path d="M5.782 5.782A7 7 0 0 0 9 19h8.5a4.5 4.5 0 0 0 1.307-.193"/><path d="M21.532 16.5A4.5 4.5 0 0 0 17.5 10h-1.79A7.008 7.008 0 0 0 10 5.07"/>',
  "503": '<rect x="2" y="6" width="20" height="8" rx="1"/><path d="M17 14v7"/><path d="M7 14v7"/><path d="M17 3v3"/><path d="M7 3v3"/><path d="M10 14 2.3 6.3"/><path d="m14 6 7.7 7.7"/><path d="m8 6 8 8"/>',
};

const COPY: Record<StaticErrorCode, { title: string; heading: string; body: string; retry: boolean }> = {
  "404": {
    title: "Page not found",
    heading: "Page not found",
    body: "The page you are looking for doesn’t exist or may have moved. Check the address, search Webcenta, or browse a popular category.",
    retry: false,
  },
  "500": {
    title: "Something went wrong",
    heading: "Something went wrong on our side",
    body: "An unexpected error stopped this page from loading. Please try again in a moment.",
    retry: true,
  },
  "502": {
    title: "Temporarily unreachable",
    heading: "Webcenta is temporarily unreachable",
    body: "Our servers didn’t respond in time. This is usually brief. Please try again in a few minutes.",
    retry: true,
  },
  "503": {
    title: "Temporarily unavailable",
    heading: "Webcenta is temporarily unavailable",
    body: "We’re carrying out maintenance or handling unusually high demand. Please try again shortly. Your account and data are safe.",
    retry: true,
  },
};

const CATEGORIES: Array<[slug: string, name: string]> = [
  ["ai", "AI & Artificial Intelligence"], ["productivity", "Productivity"], ["developer-tools", "Developer Tools"],
  ["education", "Education"], ["finance", "Finance & Accounting"], ["games", "Games"],
  ["shopping", "Shopping"], ["communication", "Communication"],
];

/** CSP for these pages: nothing but inline styles and data: images. */
export const STATIC_ERROR_CSP =
  "default-src 'none'; style-src 'unsafe-inline'; img-src data:; form-action 'self'; base-uri 'none'; frame-ancestors 'none'";

export function staticErrorPage(code: StaticErrorCode): string {
  const c = COPY[code];
  const cats = CATEGORIES.map(([s, n]) => `<li><a href="/c/${s}">${n}</a></li>`).join("");
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<meta name="color-scheme" content="light dark">
<title>${c.title} · Webcenta</title>
<style>
:root{--bg:#f7f7fb;--surface:#fff;--text:#0f1222;--muted:#4b5065;--border:#e3e5ee;--brand:#4f46e5;--brand-soft:#eef0ff;--brand-contrast:#fff}
@media (prefers-color-scheme:dark){:root{--bg:#0b0c11;--surface:#13151d;--text:#eceef6;--muted:#a3a8bd;--border:#262a37;--brand:#8b93ff;--brand-soft:#1c1f3a;--brand-contrast:#0b0c11}}
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}
body{margin:0;min-height:100vh;background:var(--bg);color:var(--text);font:16px/1.55 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
.wrap{max-width:40rem;margin:0 auto;padding:2rem 1rem 3rem}
.logo{display:inline-flex;align-items:center;gap:.5rem;color:var(--text);text-decoration:none;font-weight:800;font-size:1.15rem;letter-spacing:-.01em}
.logo b{color:var(--brand)}
main{text-align:center;margin-top:3rem}
.icon{display:grid;place-items:center;width:4rem;height:4rem;margin:0 auto;border-radius:1rem;background:var(--brand-soft);color:var(--brand)}
.code{margin:1.25rem 0 0;font-size:.8rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--brand)}
h1{margin:.25rem 0 0;font-size:clamp(1.6rem,5vw,2.2rem);line-height:1.2;letter-spacing:-.02em}
p{color:var(--muted);margin:.75rem auto 0;max-width:32rem}
.actions{display:flex;flex-wrap:wrap;gap:.75rem;justify-content:center;margin-top:1.5rem}
.btn{display:inline-flex;align-items:center;justify-content:center;height:2.5rem;padding:0 1rem;border-radius:.75rem;font-weight:600;font-size:.9rem;text-decoration:none;border:1px solid var(--border);background:var(--surface);color:var(--text)}
.btn.primary{background:var(--brand);border-color:var(--brand);color:var(--brand-contrast)}
.btn:focus-visible,input:focus-visible,a:focus-visible{outline:2px solid var(--brand);outline-offset:2px}
form{display:flex;gap:.5rem;max-width:32rem;margin:2.5rem auto 0}
input{flex:1;min-width:0;height:2.75rem;padding:0 .75rem;border-radius:.75rem;border:1px solid var(--border);background:var(--surface);color:var(--text);font:inherit;font-size:.9rem}
button{height:2.75rem;padding:0 1rem;border-radius:.75rem;border:0;background:var(--brand);color:var(--brand-contrast);font:inherit;font-weight:600;font-size:.9rem;cursor:pointer}
h2{margin:2.5rem 0 0;text-align:center;font-size:.9rem;color:var(--muted)}
ul{list-style:none;padding:0;margin:.75rem 0 0;display:flex;flex-wrap:wrap;gap:.5rem;justify-content:center}
ul a{display:inline-block;padding:.45rem .85rem;border-radius:999px;border:1px solid var(--border);background:var(--surface);color:var(--text);text-decoration:none;font-size:.85rem;font-weight:500}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
footer{margin-top:3rem;text-align:center;font-size:.75rem;color:var(--muted)}
</style>
</head>
<body>
<div class="wrap">
<header><a class="logo" href="/" aria-label="Webcenta home"><svg width="32" height="32" viewBox="0 0 32 32" aria-hidden="true"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#6366f1"/><stop offset="1" stop-color="#0ea5e9"/></linearGradient></defs><rect width="32" height="32" rx="9" fill="url(#g)"/><path d="M8 11l3 10 3-7 2 0 3 7 3-10" fill="none" stroke="#fff" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg><span>Web<b>centa</b></span></a></header>
<main>
<div class="icon"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[code]}</svg></div>
<p class="code">Error ${code}</p>
<h1>${c.heading}</h1>
<p>${c.body}</p>
<div class="actions">${c.retry ? '<a class="btn primary" href="">Try again</a><a class="btn" href="/">Go to the homepage</a>' : '<a class="btn primary" href="/">Go to the homepage</a>'}</div>
${code === "404" ? `<form action="/search" method="get" role="search"><label class="sr" for="q">Search Webcenta</label><input id="q" name="q" type="search" maxlength="120" placeholder="Search apps, tools and websites"><button type="submit">Search</button></form>
<h2>Popular categories</h2><ul>${cats}</ul>` : ""}
</main>
<footer>Webcenta · webcenta.com</footer>
</div>
</body>
</html>
`;
}
